#!/usr/bin/env bash
# ═══ Installeur René TV v4.9.3 — un seul fichier, à lancer dans WSL (Ubuntu) sous Windows 10/11 ═══
# Usage : bash installer_ReneTV.sh
set -e
V="4.9.3"; DEST="$HOME/rene-tv"
ok(){ echo -e "\e[32m✔ $*\e[0m"; }; info(){ echo -e "\e[36m➜ $*\e[0m"; }; ko(){ echo -e "\e[31m✖ $*\e[0m"; exit 1; }
echo -e "\e[1m📺 René TV v$V — installation\e[0m"
grep -qi microsoft /proc/version 2>/dev/null || ko "Ce script doit tourner dans WSL (Ubuntu) sous Windows."
command -v cmd.exe >/dev/null || ko "cmd.exe introuvable depuis WSL (interop Windows désactivée ?)."
win(){ (cd /mnt/c && cmd.exe /c "$1" 2>/dev/null | tr -d '\r'); }
WH=$(wslpath "$(win 'echo %USERPROFILE%')"); LADW=$(wslpath "$(win 'echo %LOCALAPPDATA%')")
[ -d "$WH" ] || ko "Dossier utilisateur Windows introuvable."
info "1/7 Paquets Linux (python3, curl, tar)"
NEED=""; for p in python3 curl tar; do command -v $p >/dev/null || NEED="$NEED $p"; done
[ -n "$NEED" ] && { sudo apt-get update -qq && sudo apt-get install -y -qq $NEED; }; ok "python3 / curl / tar"
info "2/7 Node.js ≥ 18 (pour fabriquer l'appli Windows)"
NV=$(node -v 2>/dev/null | sed 's/v\([0-9]*\).*/\1/'); if [ -z "$NV" ] || [ "$NV" -lt 18 ]; then curl -fsSL https://deb.nodesource.com/setup_20.x | sudo -E bash - >/dev/null && sudo apt-get install -y -qq nodejs; fi; ok "node $(node -v)"
info "3/7 FFmpeg (Windows, winget Gyan.FFmpeg, build complète gratuite)"
if win 'where ffmpeg' | grep -qi ffmpeg || [ -e "$LADW/Microsoft/WinGet/Links/ffmpeg.exe" ] || ls -d "$LADW"/Microsoft/WinGet/Packages/Gyan.FFmpeg* >/dev/null 2>&1; then ok "FFmpeg déjà présent"; else win 'winget install -e --id Gyan.FFmpeg --accept-package-agreements --accept-source-agreements' | tail -2; ok "FFmpeg installé"; fi
info "4/7 Modèles IA FSRCNNX (agrandissement ×2, GPL-3.0, igv)"
mkdir -p "$LADW/ReneTV"; U=https://github.com/igv/FSRCNN-TensorFlow/releases/download/1.1
for m in "FSRCNNX_x2_8-0-4-1.glsl e800dbc5c1c95185cc82216c597724533ff5f2880179f256eef600f03e8dc2ae" "FSRCNNX_x2_16-0-4-1.glsl d5a24a271e5d9a3f7f7a053b150c460a44c25b3cf7f770857d57cc3a2e1c9965"; do set -- $m; F="$LADW/ReneTV/$1"
 if ! echo "$2  $F" | sha256sum -c --status 2>/dev/null; then curl -fsSL -o "$F" "$U/$1" && echo "$2  $F" | sha256sum -c --status || ko "Empreinte invalide pour $1"; fi; ok "$1"; done
info "5/7 Sources René TV → $DEST"
[ -d "$DEST" ] && { mv "$DEST" "$DEST.sauve-$(date +%Y%m%d-%H%M%S)"; info "ancienne version mise de côté"; }
mkdir -p "$DEST" && sed -n '/^__CHARGE__$/,$p' "$0" | tail -n +2 | base64 -d | tar xz -C "$DEST" && ok "sources extraites"
(cd "$DEST" && python3 - <<'PY'
import hashlib,json
for f,h in json.load(open('.empreintes.json')).items():
  assert hashlib.sha256(open(f,'rb').read()).hexdigest()[:16]==h,f
print('empreintes OK')
PY
) || ko "Sources corrompues."
info "6/7 Fabrication de l'appli Windows (Electron)"
cd "$DEST" && npx --yes @electron/packager . Rene-TV --platform=win32 --arch=x64 --out "$WH/Applications-Rene" --overwrite --ignore=node_modules --ignore='\.empreintes\.json' >/dev/null && ok "appli dans $WH/Applications-Rene/Rene-TV-win32-x64"
EXE=$(wslpath -w "$WH/Applications-Rene/Rene-TV-win32-x64/Rene-TV.exe")
powershell.exe -NoProfile -Command "\$s=(New-Object -ComObject WScript.Shell).CreateShortcut([Environment]::GetFolderPath('Desktop')+'\Rene TV.lnk');\$s.TargetPath='$EXE';\$s.Save()" >/dev/null 2>&1 && ok "raccourci « Rene TV » sur le Bureau"
info "7/7 Pare-feu : autorise la télécommande (port 8765) — clique Oui dans la fenêtre Windows"
powershell.exe -NoProfile -Command "Start-Process netsh -Verb RunAs -ArgumentList 'advfirewall firewall add rule name=ReneTV-telecommande dir=in action=allow protocol=TCP localport=8765 profile=any'" >/dev/null 2>&1 && ok "règle pare-feu demandée" || info "pare-feu non modifié (télécommande peut-être bloquée)"
echo -e "\e[1;32m📺 René TV v$V installé. Double-clique « Rene TV » sur le Bureau.\e[0m"
exit 0
